#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ENV_FILE="$DIR/answers.env"
REPORTS="$DIR/reports"
mkdir -p "$REPORTS"
TOTAL_STAGES=10

banner "M3 环境摸底（#197）"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "先记下几个地址"
say "这些地址只存在本机的 $ENV_FILE 里。"
say "最后会另外生成一份把地址换成占位符的版本，贴到 GitHub（仓库是公开的）。"
echo
ask GITLAB_URL "公司 GitLab 的地址（如 https://gitlab.example.com）："
GITLAB_URL="${GITLAB_URL%/}"
write_env GITLAB_URL "$GITLAB_URL"
ask SERVER_HOST "公司服务器在内网的地址（IP 或域名）："
write_env SERVER_HOST "$SERVER_HOST"
ask PLATFORM_PORT "平台准备用的端口（直接回车用 3000）："
if [[ -z "$PLATFORM_PORT" ]]; then PLATFORM_PORT=3000; fi
write_env PLATFORM_PORT "$PLATFORM_PORT"
PLATFORM_URL="http://$SERVER_HOST:$PLATFORM_PORT"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "公司服务器：体检"
say "把 probe.sh 拷到服务器上跑一次。它只读，不改任何配置。"
step "scp \"$DIR/probe.sh\" <账号>@$SERVER_HOST:~/"
step "在服务器上：bash ~/probe.sh server > ~/server.md"
step "拷回来：scp <账号>@$SERVER_HOST:~/server.md \"$REPORTS/server.md\""
note "平时不从这台 Mac 登录服务器的话，用你习惯的方式拷过去、拷回来，放到上面的路径就行。"
pause "server.md 放好后按回车"
[[ -f "$REPORTS/server.md" ]] || warn "没找到 $REPORTS/server.md，汇总时会缺这一份；可以之后补上再重跑。"
echo
ask SERVER_HTTPS "服务器有没有 HTTPS 证书或内网域名可用（如：有 *.corp 通配证书 / 没有）："
write_env SERVER_HTTPS "$SERVER_HTTPS"
ask SERVER_FIREWALL "服务器的端口谁来开（自己能开 / 要找运维 / 不清楚）："
write_env SERVER_FIREWALL "$SERVER_FIREWALL"
ask SERVER_RIGHTS "你在服务器上有没有 sudo 和 docker 权限（都有 / 只有 docker / 都没有）："
write_env SERVER_RIGHTS "$SERVER_RIGHTS"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "公司服务器：临时监听端口 $PLATFORM_PORT"
say "接下来 ThinkPad、Mac 和 GitLab webhook 都要往服务器的 $PLATFORM_PORT 端口连一下。"
step "在服务器上另开一个终端：bash ~/probe.sh listen $PLATFORM_PORT"
step "看到「在 0.0.0.0:$PLATFORM_PORT 上监听」后别关，第 6 步做完再 Ctrl-C。"
note "server.md 里写着端口 $PLATFORM_PORT 已被占用的话：Ctrl-C 退出这个 wizard，重跑并在第 1 步换一个端口。"
pause "监听起来后按回车"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "ThinkPad：体检"
step "scp \"$DIR/probe.sh\" <账号>@<ThinkPad 地址>:~/"
step "在 ThinkPad 上：bash ~/probe.sh worker $GITLAB_URL $PLATFORM_URL > ~/thinkpad.md"
step "拷回来：scp <账号>@<ThinkPad 地址>:~/thinkpad.md \"$REPORTS/thinkpad.md\""
note "它会拉一个小镜像 curlimages/curl，测 Docker 镜像源和容器里能不能连到 Cursor。"
note "跑的时候，服务器的监听终端应该打出两行「来自 …：GET /probe-from-…」（本机一行、容器里一行）。"
pause "thinkpad.md 放好后按回车"
[[ -f "$REPORTS/thinkpad.md" ]] || warn "没找到 $REPORTS/thinkpad.md，汇总时会缺这一份。"
echo
ask THINKPAD_NETWORK "ThinkPad 怎么上网（直连 / 走公司代理，代理地址写这里，不要写密码）："
write_env THINKPAD_NETWORK "$THINKPAD_NETWORK"
ask THINKPAD_LISTENER "服务器监听终端看到 ThinkPad 的请求了吗（两行都有 / 只有本机那行 / 都没有）："
write_env THINKPAD_LISTENER "$THINKPAD_LISTENER"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "这台 Mac：体检"
ask MAC_NETWORK "这台 Mac 现在连的是哪个网络（公司内网 / VPN / 家里）："
write_env MAC_NETWORK "$MAC_NETWORK"
say "在这台 Mac 上跑 probe.sh（会拉 curlimages/curl 镜像），一般一分钟内结束……"
bash "$DIR/probe.sh" worker "$GITLAB_URL" "$PLATFORM_URL" > "$REPORTS/mac.md" 2>&1 || true
printf '  %s✓ 写好%s %s\n' "$GREEN" "$RESET" "$REPORTS/mac.md"
if grep -qE '❌|⚠' "$REPORTS/mac.md"; then
  warn "有不通过的项："
  grep -E '❌|⚠' "$REPORTS/mac.md" | cut -c1-160 | while read -r l; do note "$l"; done
fi
echo
ask MAC_LISTENER "服务器监听终端看到 Mac 的请求了吗（两行都有 / 只有本机那行 / 都没有）："
write_env MAC_LISTENER "$MAC_LISTENER"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "GitLab：webhook 能不能送到服务器"
say "需要一个你是 Maintainer 的项目，随便一个测试项目都行。"
ask WEBHOOK_PROJECT "项目路径（如 group/sub/project）："
write_env WEBHOOK_PROJECT "$WEBHOOK_PROJECT"
open_url "$GITLAB_URL/$WEBHOOK_PROJECT/-/hooks"
step "点 Add new webhook：URL 填 $PLATFORM_URL/gitlab-webhook-test，Secret token 随便填，勾 Push events，保存。"
step "在这条 webhook 的 Test 下拉里选 Push events。"
step "看页面顶部的提示，以及服务器监听终端有没有打出 X-Gitlab-Event=Push Hook。"
note "保存时就报「Requests to the local network are not allowed」或「is blocked」，说明要管理员把平台地址加进出站白名单（下一步会看）。"
ask WEBHOOK_RESULT "结果（成功 HTTP 200 / 保存时被拦，附报错原文 / 其他报错原文）："
write_env WEBHOOK_RESULT "$WEBHOOK_RESULT"
step "测完把这条 webhook 删掉；服务器上的监听现在可以 Ctrl-C 了。"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "GitLab：管理员设置"
say "这一步要管理员账号。你不是管理员，就把下面几页发给管理员，请他告诉你值。"
echo
open_url "$GITLAB_URL/admin/application_settings/network"
step "Outbound requests：「Allow requests to the local network from webhooks and integrations」勾没勾，允许列表里有什么。"
ask GL_OUTBOUND "出站请求（如：未勾，允许列表为空）："
write_env GL_OUTBOUND "$GL_OUTBOUND"
step "同一页 User and IP rate limits：哪些限流开着，各多少次。"
ask GL_RATE "限流设置："
write_env GL_RATE "$GL_RATE"
open_url "$GITLAB_URL/admin/application_settings/general"
step "Account and limit：「Require expiration dates for new access tokens」开没开；"
step "「Allow users to register any application to use GitLab as an OAuth provider」开没开。"
ask GL_TOKENS "令牌有效期和用户自建 OAuth 应用："
write_env GL_TOKENS "$GL_TOKENS"
open_url "$GITLAB_URL/admin/application_settings/repository"
step "Default branch：「Initial default branch protection」选的是哪一项。"
ask GL_BRANCH "默认分支保护："
write_env GL_BRANCH "$GL_BRANCH"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "GitLab：实测页面登录和 CLI 登录"
say "建一个临时 OAuth 应用，实测页面登录（授权码 + PKCE）和 CLI 登录（device flow），测完删掉。"
open_url "$GITLAB_URL/-/user_settings/applications"
step "Add new application：Name 填 afk-probe；Redirect URI 填 http://127.0.0.1:8765/callback；"
step "不要勾 Confidential；Scopes 只勾 read_user；保存后复制 Application ID。"
ask OAUTH_CLIENT_ID "Application ID："

say "测 device flow……"
dev=$(curl -sS -m 15 -X POST "$GITLAB_URL/oauth/authorize_device" \
  -d "client_id=$OAUTH_CLIENT_ID" -d "scope=read_user" -w '\n%{http_code}' 2>&1 || true)
dev_code=$(printf '%s' "$dev" | tail -n1)
if printf '%s' "$dev" | grep -q '"user_code"'; then
  DEVICE_RESULT="可用（HTTP ${dev_code}，返回了 user_code）"
else
  DEVICE_RESULT="不可用（HTTP ${dev_code}）：$(printf '%s' "$dev" | sed '$d' | tr '\n' ' ' | cut -c1-200)"
fi
write_env DEVICE_RESULT "$DEVICE_RESULT"

verifier=$(openssl rand -hex 32)
challenge=$(printf '%s' "$verifier" | openssl dgst -sha256 -binary | openssl base64 -A | tr '+/' '-_' | tr -d '=')
state=$(openssl rand -hex 8)
redirect="http://127.0.0.1:8765/callback"
echo
say "测页面登录：浏览器会打开授权页。"
open_url "$GITLAB_URL/oauth/authorize?client_id=$OAUTH_CLIENT_ID&redirect_uri=http%3A%2F%2F127.0.0.1%3A8765%2Fcallback&response_type=code&scope=read_user&state=$state&code_challenge=$challenge&code_challenge_method=S256"
step "点 Authorize。浏览器跳到 127.0.0.1:8765 后显示打不开，这是正常的。"
step "把地址栏里的完整地址复制过来（输入不显示）。"
ask_secret PKCE_REDIRECT "地址："
auth_code=$(printf '%s' "$PKCE_REDIRECT" | sed -n 's/.*[?&]code=\([^&]*\).*/\1/p')
token_json=$(curl -sS -m 15 -X POST "$GITLAB_URL/oauth/token" -d "client_id=$OAUTH_CLIENT_ID" \
  -d "code=$auth_code" -d "grant_type=authorization_code" -d "redirect_uri=$redirect" \
  -d "code_verifier=$verifier" 2>&1 || true)
access=$(printf '%s' "$token_json" | sed -n 's/.*"access_token":"\([^"]*\)".*/\1/p')
if [[ -n "$access" ]]; then
  me=$(curl -sS -m 15 -H "Authorization: Bearer $access" "$GITLAB_URL/api/v4/user" 2>&1 || true)
  PKCE_RESULT="可用（换到了 access token，/api/v4/user 返回了当前用户）"
  say "GitLab 上你的账号：$(printf '%s' "$me" | sed -n 's/.*"username":"\([^"]*\)".*/\1/p')，主邮箱：$(printf '%s' "$me" | sed -n 's/.*"email":"\([^"]*\)".*/\1/p')（第 10 步核对邮箱时用）"
  curl -sS -m 15 -X POST "$GITLAB_URL/oauth/revoke" -d "client_id=$OAUTH_CLIENT_ID" -d "token=$access" >/dev/null 2>&1 || true
else
  PKCE_RESULT="失败：$(printf '%s' "$token_json" | tr '\n' ' ' | cut -c1-200)"
fi
write_env PKCE_RESULT "$PKCE_RESULT"
unset access token_json PKCE_REDIRECT auth_code verifier
echo
note "device flow：$DEVICE_RESULT"
note "页面登录：$PKCE_RESULT"
step "测完到 Applications 页面把 afk-probe 删掉。"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "飞书：管理员能配合到哪一步"
say "问飞书管理员（你有飞书管理后台权限就自己看）。服务器能不能连到 open.feishu.cn 已经在 server.md 里。"
open_url "https://open.feishu.cn/app"
ask FEISHU_APP "能不能建企业自建应用并开启机器人能力："
write_env FEISHU_APP "$FEISHU_APP"
ask FEISHU_SCOPE "能不能开 im:message:send_as_bot（以应用身份发消息）权限，发布要不要审批："
write_env FEISHU_SCOPE "$FEISHU_SCOPE"
ask FEISHU_RANGE "应用可用范围以后要加人找谁、大概多快："
write_env FEISHU_RANGE "$FEISHU_RANGE"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "GitLab 和飞书的邮箱对不对得上"
say "平台按邮箱把 GitLab 用户对到飞书用户。找两三个同事核对："
step "GitLab：个人资料里的主邮箱（管理员在 Admin → Users 里能看到）。"
step "飞书：通讯录里这个人资料上的邮箱。注意飞书「企业邮箱」的地址查不到人。"
ask EMAIL_MATCH "核对了几个人、几个一致（如：3 人 3 个一致；不一致写原因，别写邮箱本身）："
write_env EMAIL_MATCH "$EMAIL_MATCH"

# ── 汇总 ──────────────────────────────────────────────────────────────────
full="$DIR/results.md"
public="$DIR/results-public.md"
{
  echo "# M3 环境摸底结果"
  echo
  echo "## 地址和回答"
  echo
  echo "- GitLab：${GITLAB_URL}；平台服务器：$PLATFORM_URL"
  echo "- 服务器 HTTPS / 域名：${SERVER_HTTPS}；端口谁开：${SERVER_FIREWALL}；权限：$SERVER_RIGHTS"
  echo "- ThinkPad 上网：${THINKPAD_NETWORK}；服务器收到 ThinkPad 的请求：$THINKPAD_LISTENER"
  echo "- Mac 所在网络：${MAC_NETWORK}；服务器收到 Mac 的请求：$MAC_LISTENER"
  echo "- GitLab webhook 送到服务器：$WEBHOOK_RESULT"
  echo "- GitLab 出站请求：$GL_OUTBOUND"
  echo "- GitLab 限流：$GL_RATE"
  echo "- GitLab 令牌 / 用户自建 OAuth 应用：$GL_TOKENS"
  echo "- GitLab 默认分支保护：$GL_BRANCH"
  echo "- CLI 登录（device flow）：$DEVICE_RESULT"
  echo "- 页面登录（授权码 + PKCE）：$PKCE_RESULT"
  echo "- 飞书自建应用 + 机器人：$FEISHU_APP"
  echo "- 飞书发消息权限 / 审批：$FEISHU_SCOPE"
  echo "- 飞书可用范围加人：$FEISHU_RANGE"
  echo "- GitLab 与飞书邮箱核对：$EMAIL_MATCH"
  echo
  for f in server thinkpad mac; do
    if [[ -f "$REPORTS/$f.md" ]]; then cat "$REPORTS/$f.md"; echo; fi
  done
} > "$full"

# 公开版：GitLab、服务器、同一公司域名下的主机、IPv4、各机器主机名都换成占位符
gl_host=$(printf '%s' "$GITLAB_URL" | sed -E 's#^[a-z]+://##; s#[:/].*$##')
domain=""
if ! [[ "$gl_host" =~ ^[0-9.]+$ ]]; then domain=$(printf '%s' "$gl_host" | awk -F. 'NF >= 2 {print $(NF-1) "." $NF}'); fi
hosts=$(sed -n 's/^## 构建机 \([^ ]*\) ·.*/\1/p' "$REPORTS"/*.md 2>/dev/null | tr '\n' ' ' || true)
GL_HOST="$gl_host" SRV_HOST="$SERVER_HOST" DOMAIN="$domain" HOSTS="$hosts" perl -pe '
  BEGIN { @h = grep { length } split / /, $ENV{HOSTS} }
  s/\Q$ENV{GL_HOST}\E/<gitlab>/g if length $ENV{GL_HOST};
  s/\Q$ENV{SRV_HOST}\E/<server>/g if length $ENV{SRV_HOST};
  s/[A-Za-z0-9.-]+\.\Q$ENV{DOMAIN}\E\b/<内网域名>/g if length $ENV{DOMAIN};
  s/\b\Q$ENV{DOMAIN}\E\b/<内网域名>/g if length $ENV{DOMAIN};
  for my $x (@h) { s/\Q$x\E/<主机名>/g }
  s/\b(?:\d{1,3}\.){3}\d{1,3}\b/<ip>/g;
  s/^(- 主机名：).*/$1<已隐去>/;
' "$full" > "$public"

finish
say "完整版（只留本机）：$full"
say "公开版（贴 GitHub 用）：$public"
warn "贴之前把公开版扫一眼：公司域名以外的代理地址、项目路径这类东西不会被自动隐去。"
say "看过没问题后，告诉 Claude 一声，它会从这台 Mac 上取走公开版贴到 #197。"
echo
}

run_wizard "$@"; exit
